ACTIONS = {key: text for group in GROUPS.values() for key, text in group}

def available(transcript, target_name):
    context = topic(transcript)
    if context == 'serious':
        return {}
    themed = 'formal_style' if context == 'warm_style' else context
    choices = dict(GROUPS['general'] + GROUPS.get(themed, ()) if themed != 'general' else GROUPS['general'])
    return {key: text.format(target=target_name) for key, text in choices.items() if target_name or '{target}' not in text}
